*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg:          #f5f6fa;
  --color-surface:     #ffffff;
  --color-border:      #c8ccd8;
  --color-border-focus:#3b6ff5;
  --color-border-error:#c0392b;
  --color-text:        #1a1d2e;
  --color-text-muted:  #5a5f7a;
  --color-required:    #c0392b;
  --color-error-bg:    #fff0ee;
  --color-error-text:  #8b1a12;
  --color-success-bg:  #e8f8f0;
  --color-success-text:#1a5c38;
  --color-btn:         #3b6ff5;
  --color-btn-hover:   #2a58db;
  --color-btn-text:    #ffffff;
  --radius:            10px;
  --shadow:            0 4px 24px rgba(30,34,60,.09);
  --transition:        .18s ease;
}

html { font-size: 100%; }

body {
  min-height: 100vh;
  background: var(--color-bg);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
  color: var(--color-text);
  line-height: 1.6;
  padding: 2rem 1rem;
}

/* ── Skip link ────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -9999px;
  left: 1rem;
  background: var(--color-btn);
  color: var(--color-btn-text);
  padding: .5rem 1rem;
  border-radius: var(--radius);
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus { top: 1rem; }

/* ── Page layout ──────────────────────────────────────────────── */
header {
  text-align: center;
  margin-bottom: 2.5rem;
}

header h1 {
  font-size: clamp(1.6rem, 4vw, 2.2rem);
  font-weight: 700;
  letter-spacing: -.02em;
  color: var(--color-text);
}

header p {
  margin-top: .4rem;
  color: var(--color-text-muted);
  font-size: .975rem;
}

main {
  max-width: 540px;
  margin: 0 auto;
}

/* ── Card ─────────────────────────────────────────────────────── */
.form-card {
  background: var(--color-surface);
  border-radius: calc(var(--radius) * 1.5);
  box-shadow: var(--shadow);
  padding: clamp(1.5rem, 5vw, 2.5rem);
}

/* ── Required legend ──────────────────────────────────────────── */
.required-legend {
  font-size: .85rem;
  color: var(--color-text-muted);
  margin-bottom: 1.5rem;
}

.required-legend .req-marker {
  color: var(--color-required);
  font-weight: 700;
  margin-right: .2em;
}

/* ── Form fields ──────────────────────────────────────────────── */
.form-field {
  display: flex;
  flex-direction: column;
  gap: .3rem;
  margin-bottom: 1.4rem;
}

.form-field label {
  font-size: .9rem;
  font-weight: 600;
  color: var(--color-text);
}

.req-star {
  color: var(--color-required);
  margin-left: .2em;
  font-weight: 700;
}

.form-field input {
  width: 100%;
  padding: .65rem .85rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius);
  font-size: 1rem;
  font-family: inherit;
  color: var(--color-text);
  background: var(--color-surface);
  transition: border-color var(--transition), box-shadow var(--transition);
  appearance: none;
}

.form-field input:focus {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
  border-color: var(--color-border-focus);
}

.form-field input[aria-invalid="true"] {
  border-color: var(--color-border-error);
}

.form-field input[aria-invalid="true"]:focus {
  outline-color: var(--color-border-error);
  border-color: var(--color-border-error);
}

/* ── Help text ────────────────────────────────────────────────── */
.help-text {
  font-size: .82rem;
  color: var(--color-text-muted);
}

/* ── Error message ────────────────────────────────────────────── */
.error-msg {
  display: none;
  font-size: .82rem;
  color: var(--color-error-text);
  background: var(--color-error-bg);
  border-left: 3px solid var(--color-border-error);
  padding: .35rem .6rem;
  border-radius: 0 4px 4px 0;
}

.error-msg[data-visible="true"] { display: block; }

/* ── Submit button ────────────────────────────────────────────── */
.btn-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  padding: .75rem 1.5rem;
  margin-top: .4rem;
  background: var(--color-btn);
  color: var(--color-btn-text);
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background var(--transition), transform var(--transition);
}

.btn-submit:hover  { background: var(--color-btn-hover); }
.btn-submit:active { transform: scale(.98); }
.btn-submit:focus  {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

/* ── Status message (live region) ────────────────────────────── */
#form-status {
  margin-top: 1.25rem;
  padding: .85rem 1rem;
  border-radius: var(--radius);
  font-size: .93rem;
  font-weight: 500;
  display: none;
}

#form-status[data-type="success"] {
  display: block;
  background: var(--color-success-bg);
  color: var(--color-success-text);
  border: 1.5px solid #60c89a;
}

#form-status[data-type="error"] {
  display: block;
  background: var(--color-error-bg);
  color: var(--color-error-text);
  border: 1.5px solid var(--color-border-error);
}

/* ── Forced colors (Windows High Contrast) ────────────────────── */
@media (forced-colors: active) {
  .form-field input,
  .btn-submit {
    forced-color-adjust: auto;
  }

  .error-msg { border-left-color: LinkText; }
  .btn-submit { background: ButtonFace; color: ButtonText; }
}

/* ── Reduced motion ───────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}

/* ── Reflow at 320 px ─────────────────────────────────────────── */
@media (max-width: 360px) {
  .form-card { padding: 1.25rem 1rem; }
}
