/* ── Validation rules ─────────────────────────────────────────── */
const RULES = {
  name: {
    validate(v) {
      if (!v.trim()) return 'Error: Full name is required.';
      if (v.trim().length < 2) return 'Error: Enter at least 2 characters.';
      return null;
    }
  },
  email: {
    validate(v) {
      if (!v.trim()) return 'Error: Email address is required.';
      // RFC-5322 simplified — covers realistic inputs
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim()))
        return 'Error: Enter a valid email address, e.g. name@example.com.';
      return null;
    }
  },
  phone: {
    validate(v) {
      if (!v.trim()) return null; // optional
      // Allow digits, spaces, hyphens, dots, parentheses, leading +
      if (!/^\+?[\d\s\-().]{7,20}$/.test(v.trim()))
        return 'Error: Enter a valid phone number, e.g. +1 (555) 123-4567.';
      return null;
    }
  }
};

/* ── Helpers ──────────────────────────────────────────────────── */
function getField(id)    { return document.getElementById(id); }
function getError(id)    { return document.getElementById(`${id}-error`); }

function setValidity(input, errorEl, message) {
  if (message) {
    input.setAttribute('aria-invalid', 'true');
    errorEl.textContent = message;
    errorEl.setAttribute('data-visible', 'true');
  } else {
    input.removeAttribute('aria-invalid');
    errorEl.textContent = '';
    errorEl.removeAttribute('data-visible');
  }
}

function validateField(id) {
  const input = getField(id);
  const errorEl = getError(id);
  const msg = RULES[id].validate(input.value);
  setValidity(input, errorEl, msg);
  return msg === null;
}

/* ── Live (blur) validation ───────────────────────────────────── */
['name', 'email', 'phone'].forEach(id => {
  const input = getField(id);

  input.addEventListener('blur', () => validateField(id));

  // Re-validate on input once already marked invalid (immediate feedback)
  input.addEventListener('input', () => {
    if (input.getAttribute('aria-invalid') === 'true') validateField(id);
  });
});

/* ── Submit ───────────────────────────────────────────────────── */
document.getElementById('contact-form').addEventListener('submit', e => {
  e.preventDefault();

  const fields  = ['name', 'email', 'phone'];
  const results = fields.map(id => ({ id, valid: validateField(id) }));
  const firstInvalid = results.find(r => !r.valid);

  const statusEl = document.getElementById('form-status');

  if (firstInvalid) {
    getField(firstInvalid.id).focus();
    statusEl.removeAttribute('data-type');
    statusEl.style.display = 'none';
    return;
  }

  // Simulate successful submission
  statusEl.setAttribute('data-type', 'success');
  statusEl.textContent = '✓ Your message has been sent. We\'ll be in touch soon!';
  statusEl.focus();

  e.target.reset();
  ['name', 'email', 'phone'].forEach(id => {
    const input = getField(id);
    const errorEl = getError(id);
    input.removeAttribute('aria-invalid');
    errorEl.removeAttribute('data-visible');
    errorEl.textContent = '';
  });
});
