const RULES = {
  name: {
    validate(v) {
      if (!v.trim()) return 'Error: Full name is required.';
      if (v.trim().length < 2) return 'Error: Enter at least 2 characters.';
      return null;
    }
  },
  email: {
    validate(v) {
      if (!v.trim()) return 'Error: Email address is required.';
      // RFC-5322 simplified — covers realistic inputs
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim()))
        return 'Error: Enter a valid email address, e.g. name@example.com.';
      return null;
    }
  },
  phone: {
    validate(v) {
      if (!v.trim()) return null; // optional
      // Allow digits, spaces, hyphens, dots, parentheses, leading +
      if (!/^\+?[\d\s\-().]{7,20}$/.test(v.trim()))
        return 'Error: Enter a valid phone number, e.g. +1 (555) 123-4567.';
      return null;
    }
  }
};

/* ── Helpers ──────────────────────────────────────────────────── */
function getField(id)    { return document.getElementById(id); }
function getError(id)    { return document.getElementById(`${id}-error`); }

function setValidity(input, errorEl, message) {
  if (message) {
    input.setAttribute('aria-invalid', 'true');
    errorEl.textContent = message;
    errorEl.setAttribute('data-visible', 'true');
  } else {
    input.removeAttribute('aria-invalid');
    errorEl.textContent = '';
    errorEl.removeAttribute('data-visible');
  }
}

